const bank=<Q>[
 Q('Enteros','La temperatura era −6 °C y aumentó 14 °C. ¿Temperatura final?',['8 °C','−20 °C','20 °C','−8 °C'],'8 °C','Avanza 14 posiciones desde −6.'),
